---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Plan review: Check the agent's plan, edit steps, then let it run.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change plan-review.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './plan-review.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="plan-review" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="plx panel">
  <div class="plx-h"><span class="think plx-mk"><i></i><i></i><i></i><i></i></span><div class="plx-ht"><b>Plan: redesign the pricing page</b><span class="muted plx-st">About 4 min</span></div><span class="plx-tm num" aria-label="Elapsed"></span></div>
  <ol class="plx-list"></ol>
  <button class="plx-add"><svg class="i xs"><use href="#i-plus"/></svg>Add a step</button>
  <div class="plx-f"><span class="muted plx-n">Click a step to edit it</span><button class="pill ghost sm plx-chg">Ask for changes</button><button class="pill primary sm plx-go">Approve plan</button></div>
</div>
  </Fragment></div>
</div>
<script>
  import './plan-review.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Plan review ---------- */
/* the plan the agent posts in the chat: no container; with .panel it becomes a card */
.plx{padding:14px 0;display:flex;flex-direction:column;gap:10px;--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
.plx.panel{padding:var(--dm-s-4)}
.plx-h{display:flex;align-items:center;gap:10px}
/* the header's mark sits in the steps' 32px number column, centred */
.plx-mk{color:var(--dm-accent-fg,var(--dm-accent));margin-inline:9px}
.plx-ht{display:flex;flex-direction:column;min-width:0}
.plx-ht b{font-weight:500;font-size:13.5px}
.plx-st{font-size:12.5px}
/* every part on shared columns, in every style (owner, 18 Nov): the header's mark and each step's number are centred in one
   32px column, so the steps' words start where the title's do; a step's hover fill spans the content and no wider */
.plx-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;counter-reset:s}
.plx-s{display:flex;align-items:flex-start;gap:10px;padding:7px 6px 7px 0;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;transition:background .25s,opacity .35s;position:relative}
@media (hover:hover) and (pointer:fine){.plx-s:hover{background:var(--dm-row)}}
.plx-s .n{width:20px;height:20px;margin:1px 6px 0;border-radius:50%;background:var(--dm-chip);display:grid;place-items:center;font-size:11px;font-variant-numeric:tabular-nums;color:var(--dm-muted);flex:none;transition:background .35s,color .35s}
@media (hover:hover) and (pointer:fine){.plx-s:hover .n{background:var(--dm-surface)}}
.plx-s .b{flex:1;min-width:0;display:flex;flex-direction:column}
/* (a 20px line, with the number on it: the number and the words share one centre, with even room above and below) */
.plx-s .t{min-width:0;outline:0;border-radius:var(--dm-r-tiny,5px);padding:1px 3px;margin:0 -3px;line-height:20px}
/* the line a step reports: it opens under the step, in the step's colour while it waits on something */
.plx-s .d{font-size:12px;color:var(--dm-muted);display:grid;grid-template-rows:0fr;transition:grid-template-rows .32s var(--dm-ease)}
.plx-s .d.on{grid-template-rows:1fr}
.plx-s .d>span{overflow:hidden;min-height:0}
/* a running step's note ("Retrying") has the loader's sweep; the note it replaces fades out in its own colour, unswept */
.plx-s .d>.shim.out{color:inherit;background:none;animation:none}
.plx-s .d.warn{color:var(--dm-warn)}
.plx-tm{margin-left:auto;font-size:12px;color:var(--dm-muted)}
.plx-tm:empty{display:none}
.plx-s .n .spin{width:10px;height:10px}
.plx-s .t:focus{background:var(--dm-surface);box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
/* (the skip button takes no more height than a step's line, so a step has the same room above and below its words) */
.plx-s .ib{width:24px;height:24px;margin-block:-1.25px;opacity:0;transition:opacity .2s}
.plx-s .ib:focus-visible{opacity:1}
@media (hover:hover) and (pointer:fine){.plx-s:hover .ib{opacity:1}}
.plx-s.off{opacity:.45}
.plx-s.off .t{text-decoration:line-through}
.plx-s.run .n{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
/* a finished step is neutral with the green tick, no green fill (owner, 18 Nov) */
.plx-s.done .n{background:var(--dm-chip);color:var(--dm-ok)}
.plx-s.retry .n{background:var(--dm-warn-bg);color:var(--dm-warn)}
.plx-s.edited .t::after{content:"edited";margin-left:6px;font-size:11px;color:var(--dm-accent-fg,var(--dm-accent))}
.plx-add{display:flex;align-items:center;gap:10px;font-size:12.5px;color:var(--dm-fg2);padding:6px 0;align-self:stretch;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)))}
.plx-add .i{margin-inline:10px}
@media (hover:hover) and (pointer:fine){.plx-add:hover{color:var(--dm-fg);background:var(--dm-row)}}
/* the footer's buttons end on the content's right edge, also on a phone, where the note beside them is left out */
.plx-f{display:flex;align-items:center;justify-content:flex-end;gap:6px}
/* the footer sits under a hairline in Soft and Blueprint, in every state (owner, 21 Nov: "shouldn't there be a divider line
   there?"), 16px under the last step and 16px over its buttons, as the card's own edges are; Clean's is a foot strip (below) */
.plx-f{margin-top:6px;padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.plx-n{flex:1;font-size:12px;min-width:0}
@media (max-width:480px){.plx-n{display:none}}
/* Clean (lead and owner, 18 Nov): a card with the plan and an off-white foot strip, everything on shared columns. Its
   content sits 16px in from every edge: the header's mark sits in a 32px neutral tile, and each step's number circle is
   centred in that same 32px column, as Add a step's plus is, so every step's words start where the title's do. A step's
   hover fill spans the content, from the tile's left edge to the content's right edge, never wider; the skip button is
   centred in a 32px column at its end. The foot strip's hint starts at the content's left edge, and its buttons sit 8px from
   the card's edges, the 28px buttons' 14px ends and 8px making the card's 22px corner. A queued step is a hairline circle with its number, the step in hand a spinner ring in the accent (white in dark mode), one
   waiting out a problem an orange ring with its clock, a finished one a neutral circle with a green ring and tick (no green
   fill, as a finished row has none): two hues, and only on
   steps that run or have run. Each step's line comes in only once the agent has done it (or is waiting on something), and
   the header sums the run up only once it is over. "edited" is quiet grey text */
:root[data-style="clean"] .plx.panel,:root [data-style="clean"] .plx.panel,:root [data-style="clean"].plx.panel{padding:16px 16px 0}
:root[data-style="clean"] .plx.panel.growing,:root [data-style="clean"] .plx.panel.growing,:root [data-style="clean"].plx.panel.growing{overflow-clip-margin:0px}
:root[data-style="clean"] .plx-h,:root [data-style="clean"] .plx-h,:root [data-style="clean"].plx-h{position:relative;gap:12px}
:root[data-style="clean"] .plx-h::before,:root [data-style="clean"] .plx-h::before,:root [data-style="clean"].plx-h::before{content:"";position:absolute;left:0;top:50%;width:32px;height:32px;margin-top:-16px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-chip);box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .plx-mk,:root [data-style="clean"] .plx-mk,:root [data-style="clean"].plx-mk{margin-inline:9px;color:var(--dm-accent-mark)}
:root[data-style="clean"] .plx-ht b,:root [data-style="clean"] .plx-ht b,:root [data-style="clean"].plx-ht b{line-height:20px}
:root[data-style="clean"] .plx-st,:root [data-style="clean"] .plx-st,:root [data-style="clean"].plx-st{line-height:18px}
:root[data-style="clean"] .plx-tm,:root [data-style="clean"] .plx-tm,:root [data-style="clean"].plx-tm{font-variant-numeric:tabular-nums}
:root[data-style="clean"] .plx-list,:root [data-style="clean"] .plx-list,:root [data-style="clean"].plx-list{margin:0}
:root[data-style="clean"] .plx-s,:root [data-style="clean"] .plx-s,:root [data-style="clean"].plx-s{gap:12px;padding:7px 6px 7px 0;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)));transition:background-color var(--dm-t-fast) var(--dm-ease),opacity var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .plx-s .n,:root [data-style="clean"] .plx-s .n,:root [data-style="clean"].plx-s .n{margin:1px 6px 0;background:none;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line-strong) 50%,transparent);transition:background-color var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .plx-s:hover .n,:root [data-style="clean"] .plx-s:hover .n,:root [data-style="clean"].plx-s:hover .n{background:var(--dm-surface)}}
:root[data-style="clean"] .plx-s.run .n,:root [data-style="clean"] .plx-s.run .n,:root [data-style="clean"].plx-s.run .n{box-shadow:none;color:var(--dm-fg)}
:root[data-style="clean"] .plx-s.run .n .spin,:root [data-style="clean"] .plx-s.run .n .spin,:root [data-style="clean"].plx-s.run .n .spin{width:20px;height:20px;border:1.5px solid var(--dm-line);border-top-color:var(--dm-accent-mark);animation-duration:.9s}
:root[data-style="clean"] .plx-s.retry .n,:root [data-style="clean"] .plx-s.retry .n,:root [data-style="clean"].plx-s.retry .n{background:none;box-shadow:inset 0 0 0 1.5px var(--dm-warn-mark);color:var(--dm-warn-mark)}
:root[data-style="clean"] .plx-s.done .n,:root [data-style="clean"] .plx-s.done .n,:root [data-style="clean"].plx-s.done .n{background:var(--dm-surface);box-shadow:inset 0 0 0 1.5px var(--dm-ok-mark);color:var(--dm-ok-mark)}
:root[data-style="clean"] .plx-s.done .n .i,:root [data-style="clean"] .plx-s.done .n .i,:root [data-style="clean"].plx-s.done .n .i{width:11px;height:11px;stroke-width:2.4}
:root[data-style="clean"] .plx-s.edited .t::after,:root [data-style="clean"] .plx-s.edited .t::after,:root [data-style="clean"].plx-s.edited .t::after{color:var(--dm-muted)}
:root[data-style="clean"] .plx-add,:root [data-style="clean"] .plx-add,:root [data-style="clean"].plx-add{align-self:stretch;gap:12px;margin:-4px 0 0;padding:6px 0;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)));transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .plx-add .i,:root [data-style="clean"] .plx-add .i,:root [data-style="clean"].plx-add .i{margin-inline:10px}
:root[data-style="clean"] .plx.panel .plx-f .plx-stop,:root [data-style="clean"] .plx.panel .plx-f .plx-stop,:root [data-style="clean"].plx.panel .plx-f .plx-stop{margin-right:0}
:root[data-style="clean"] .plx.panel .plx-f,:root [data-style="clean"] .plx.panel .plx-f,:root [data-style="clean"].plx.panel .plx-f{justify-content:flex-end;gap:4px;margin:6px -16px 0;padding:var(--dm-strip-y) 16px;border-top:1px solid var(--dm-line);background:var(--dm-strip);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .plx.panel .plx-n,:root [data-style="clean"] .plx.panel .plx-n,:root [data-style="clean"].plx.panel .plx-n{padding-left:0}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, ctl, enter, grow, hoverGlide, html, stagger, swap } from '../core/core.js';
DM.def('plan-review', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{plus}', I('plus','xs'));
  // each step, and the line it reports when it's done
  const S = [
    ['Read the pricing frames and the brand tokens', '6 frames and 42 tokens read'],
    ['Compare against the three competitor pages', '3 pages compared'],
    ['Simplify the plan cards to one CTA each', 'Plan cards now have one CTA each'],
    ['Move the FAQ below the comparison table', 'FAQ now sits under the table'],
    ['Write a summary of every change', 'Summary added to Pricing v4']
  ];
  const list = $('.plx-list', r), st = $('.plx-st', r), tm = $('.plx-tm', r), go = $('.plx-go', r), f = $('.plx-f', r);
  if (!r.closest('.ahx')) c.offs.push(hoverGlide(list, '.plx-s'));
  const row = (t, i) => `<li class="plx-s"><span class="n">${i + 1}</span><span class="b"><span class="t" contenteditable="true" spellcheck="false" role="textbox" aria-label="Step ${i + 1}">${t[0]}</span><span class="d"><span></span></span></span><button class="ib plx-x" aria-label="Skip step" data-tip="Skip step">${I('x','xs')}</button></li>`;
  list.innerHTML = S.map(row).join(''); stagger($$('.plx-s', list), 60, 100);
  const count = () => { const on = $$('.plx-s:not(.off)', list); on.forEach((s, i) => $('.n', s).textContent = i + 1); $$('.plx-s.off .n', list).forEach(n => n.textContent = '–'); swap(st, 'About ' + Math.max(1, Math.round(on.length * .8)) + ' min'); };
  function bind(s, done){
    const t = $('.t', s), orig = t.textContent; s._done = done || 'Done';
    t.onkeydown = e => { if (e.key === 'Enter'){ e.preventDefault(); t.blur(); } };
    t.onblur = () => { const ed = t.textContent.trim() !== orig; s.classList.toggle('edited', ed); if (ed) s._done = 'Done as you wrote it'; };
    $('.plx-x', s).onclick = () => { const off = s.classList.toggle('off'); $('.plx-x', s).dataset.tip = off ? 'Include step' : 'Skip step'; $('.plx-x', s).setAttribute('aria-label', off ? 'Include step' : 'Skip step'); $('.plx-x', s).innerHTML = I(off ? 'undo' : 'x', 'xs'); count(); };
  }
  $$('.plx-s', list).forEach((s, i) => bind(s, S[i][1]));
  // the panel grows with the plan (owner, 17 Nov): no room kept for the final state, the height eases open as done lines
  // and notes arrive, and the panel stays centred in its stage as it grows
  const root = $('.plx', r);
  c.offs.push(grow(root));
  $('.plx-add', r).onclick = () => { const s = html(row(['New step'], $$('.plx-s', list).length)); list.appendChild(s); enter(s); bind(s); count(); const t = $('.t', s); t.focus({ preventScroll:true }); document.getSelection().selectAllChildren(t); };
  $('.plx-chg', r).onclick = () => { swap($('.plx-n', r), 'Tell the agent what to change in chat'); };
  const clock = ms => { const s = Math.floor(ms / 1000); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0'); };
  const note = (s, text, tone) => { const d = $('.d', s); d.className = 'd on' + (tone ? ' ' + tone : ''); swap(d.firstElementChild, text); };
  // the person's turn (editing and approving the plan) holds under a resting mouse, so it never moves what they are about to
  // click; once approved, the agent's run keeps working under it, as an agent at work does (DM.PLAYS): its waits go through a
  // controller of its own, which nothing holds, and stop with the demo
  const agent = ctl(); c.offs.push(() => agent.stop());
  go.onclick = () => c.run(async () => {
    $$('.t', list).forEach(t => { t.contentEditable = 'false'; t.removeAttribute('role'); }); $('.plx-add', r).hidden = true;
    // the approved plan is fixed: the skip buttons keep their space but can't be used
    $$('.plx-x', list).forEach(b => { b.disabled = true; b.style.visibility = 'hidden'; });
    // the status line says it is running and how long is left; the foot keeps only Stop (no line repeating the head)
    f.innerHTML = `<span class="muted plx-n"></span><button class="pill ghost sm plx-stop">${I('stop','xs')}Stop</button>`; stagger([...f.children], 50);
    let stop = false; $('.plx-stop', f).onclick = () => stop = true;
    $('.plx-mk', r).classList.add('on');
    const t0 = performance.now(), tick = agent.every(250, () => tm.textContent = clock(performance.now() - t0)); tm.textContent = '0:00'; enter(tm);
    const on = $$('.plx-s:not(.off)', list), n = s => $('.n', s), txt = s => $('.t', s);
    try {
      for (let i = 0; i < on.length && !stop; i++){
        const s = on[i]; s.classList.add('run'); txt(s).classList.add('shim'); n(s).innerHTML = '<span class="spin"></span>'; st.classList.add('shim'); swap(st, 'About ' + Math.max(1, Math.round((on.length - i) * .8)) + ' min left'); await agent.wait(900);
        // the second step hits a rate limit: the agent waits it out, counting down, and tries again
        if (s === $$('.plx-s', list)[1] && !stop){
          s.classList.replace('run', 'retry'); txt(s).classList.remove('shim'); n(s).innerHTML = I('clock','xs');
          for (let k = 3; k > 0 && !stop; k--){ note(s, `Rate limited by the browser tool. Retrying in ${k}s`, 'warn'); await agent.wait(1000); }
          if (stop) break;
          s.classList.replace('retry', 'run'); txt(s).classList.add('shim'); n(s).innerHTML = '<span class="spin"></span>'; note(s, 'Retrying'); $('.d>span', s).classList.add('shim'); await agent.wait(700);
          s._done += ', after 1 retry';
        }
        s.classList.remove('run'); txt(s).classList.remove('shim'); $('.d>span', s).classList.remove('shim'); s.classList.add('done'); n(s).innerHTML = I('check','xs'); enter(n(s).firstElementChild); note(s, s._done);
      }
    } finally { clearInterval(tick); }
    $('.plx-mk', r).classList.remove('on');
    $$('.plx-s.run', list).forEach(s => { s.classList.remove('run', 'retry'); txt(s).classList.remove('shim'); $('.d>span', s).classList.remove('shim'); n(s).textContent = '–'; note(s, 'Not started'); });
    // a finished plan has no elapsed clock (owner, 18 Nov): the status line says how long it took
    // See changes is the white outlined secondary (owner, 23 Nov); inside Agent harness (Phase II) it keeps its grey one for now
    tm.textContent = ''; st.classList.remove('shim');
    swap(st, stop ? 'Stopped, progress kept' : 'Done in ' + clock(performance.now() - t0) + '. 4 frames updated'); f.innerHTML = `<span class="muted plx-n"></span><button class="pill ${r.closest('.ahx') ? 'soft' : 'line'} sm">${I('eye','xs')}See changes</button>`; enter(f.lastElementChild);
  });
  // the preview's story: rewrite a step, approve, and watch the agent work through a rate limit to the end
  c.story(async s => {
    await s.beat(3);
    const step = $$('.plx-s', list)[2], t = $('.t', step);
    // the demo types into the step without taking the focus: a caret would make the page follow it
    await s.tap(t); await s.beat(1);
    for (const ch of ' each'){ t.textContent = t.textContent.slice(0, -1); await s.beat(.12); }
    for (const ch of ', annual price first'){ t.textContent += ch; await s.beat(.09); }
    await s.beat(1); t.onblur(); await s.beat(2);
    await s.tap(go); s.away();
    await s.until(() => $('.plx-f .pill:is(.line,.soft)', r));
  });
});
